require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('donor');$q=db()->prepare('SELECT * FROM notification_logs WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([(int)$user['id']]);$rows=$q->fetchAll();$pageTitle='Alerts';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
